const FRAME_BLOCKED_DOMAINS = [
    'spotify.com',
    'apple.com',
    'ascap.com',
    'bmi.com',
    'themlc.com',
    'soundexchange.com',
    'copyright.gov',
    'instagram.com',
    'youtube.com',
    'youtu.be',
    'github.com',
    'x.com',
    'twitter.com',
    'tiktok.com',
    'facebook.com',
    'distrokid.com',
    'tunecore.com',
    'cdbaby.com',
] as const;

function isKnownFrameBlockedUrl(rawInput: string): boolean {
    try {
        const hostname = new URL(rawInput).hostname.toLowerCase();
        return FRAME_BLOCKED_DOMAINS.some(
            domain => hostname === domain || hostname.endsWith(`.${domain}`)
        );
    } catch {
        return false;
    }
}

