import { z } from 'zod';

export const RIGHTS_LIMITS = Object.freeze({ globalSessions: 5, ownerSessions: 1, sessionMs: 120 * 60_000, idleMs: 15 * 60_000, rememberMs: 7 * 86400_000, ticketMs: 60_000, depositBytes: 500 * 1024 * 1024 });
