  1	import log from 'electron-log';
  2	import { BrowserWindow, WebContentsView, ipcMain, session, shell, type IpcMainInvokeEvent } from 'electron';
  3	import { z } from 'zod';
  4	import { validateSender } from '../utils/ipc-security';
  5	import { validateSafeUrlAsync } from '../utils/network-security';
  6	
  7	export interface BoardroomBrowserState {
  8	    url: string;
  9	    title: string;
 10	    isLoading: boolean;
 11	    canGoBack: boolean;
 12	    canGoForward: boolean;
 13	    error: string | null;
 14	}
 15	
 16	const BoundsSchema = z.object({
 17	    x: z.number().int().nonnegative(),
 18	    y: z.number().int().nonnegative(),
 19	    width: z.number().int().nonnegative(),
 20	    height: z.number().int().nonnegative(),
 21	    visible: z.boolean().default(true),
 22	}).strict();
 23	
 24	const NavigateSchema = z.object({
 25	    url: z.string().trim().min(1).max(4096),
 26	}).strict();
 27	
 28	const AttachSchema = z.object({
 29	    initialUrl: z.string().trim().max(4096).optional(),
 30	}).strict();
 31	
 32	class BoardroomBrowserController {
 33	    private view: WebContentsView | null = null;
 34	    private pageRevision = 0;
 35	    private ownerWindow: BrowserWindow | null = null;
 36	    private partitionSession = session.fromPartition('persist:boardroom-browser');
 37	
 38	    private currentState: BoardroomBrowserState = {
 39	        url: 'https://artists.spotify.com',
 40	        title: 'Spotify for Artists',
 41	        isLoading: false,
 42	        canGoBack: false,
 43	        canGoForward: false,
 44	        error: null,
 45	    };
 46	
 47	    constructor() {
 48	        // Harden the partition session
 49	        this.partitionSession.setPermissionRequestHandler((_webContents, _permission, callback) => callback(false));
 50	        this.partitionSession.setPermissionCheckHandler(() => false);
 51	        // Validate page requests as well as frame navigations and redirects:
 52	        // scripts and fetches can otherwise reach private network destinations.
 53	        this.partitionSession.webRequest.onBeforeRequest(
 54	            (details, callback) => {
 55	                // WebSocket URLs use the same network hosts as HTTP(S).
 56	                const checkUrl = details.url.replace(/^ws:/i, 'http:').replace(/^wss:/i, 'https:');
 57	                if (!/^https?:/i.test(checkUrl)) {
 58	                    callback({ cancel: false });
 59	                    return;
 60	                }
 61	                let settled = false;
 62	                const finish = (cancel: boolean) => {
 63	                    if (settled) return;
 64	                    settled = true;
 65	                    clearTimeout(timeout);
 66	                    callback({ cancel });
 67	                };
 68	                const timeout = setTimeout(() => finish(true), 5_000);
 69	                void validateSafeUrlAsync(checkUrl).then(
 70	                    () => finish(false),
 71	                    () => finish(true),
 72	                );
 73	            },
 74	        );
 75	    }
 76	
 77	    private emitState() {
 78	        if (!this.ownerWindow || this.ownerWindow.isDestroyed()) return;
 79	        try {
 80	            this.ownerWindow.webContents.send('boardroom-browser:state-changed', { ...this.currentState });
 81	        } catch (err) {
 82	            log.warn('[BoardroomBrowser] Failed to emit state:', err);
 83	        }
 84	    }
 85	
 86	    private updateState(partial: Partial<BoardroomBrowserState>) {
 87	        this.currentState = { ...this.currentState, ...partial };
 88	        this.emitState();
 89	    }
 90	
 91	    private normalizeUrl(input: string): string {
 92	        const trimmed = input.trim();
 93	        if (/^[a-zA-Z][a-zA-Z0-9+.-]*:/.test(trimmed)) {
 94	            return trimmed;
 95	        }
 96	        // If user typed a search query or bare domain
 97	        if (trimmed.includes('.') && !trimmed.includes(' ')) {
 98	            return `https://${trimmed}`;
 99	        }
100	        return `https://www.google.com/search?q=${encodeURIComponent(trimmed)}`;
101	    }
102	
103	    public async attach(event: IpcMainInvokeEvent, rawInput: unknown): Promise<{ success: boolean; state: BoardroomBrowserState }> {
104	        const input = AttachSchema.parse(rawInput || {});
105	        const targetUrl = this.normalizeUrl(input.initialUrl || this.currentState.url || 'https://artists.spotify.com');
106	
107	        await validateSafeUrlAsync(targetUrl);
108	
109	        const parentWin = BrowserWindow.fromWebContents(event.sender);
110	        if (!parentWin) {
111	            throw new Error('Parent window not found for Boardroom browser.');
112	        }
113	
114	        this.ownerWindow = parentWin;
115	
116	        if (!this.view) {
117	            this.view = new WebContentsView({
118	                webPreferences: {
119	                    session: this.partitionSession,
120	                    nodeIntegration: false,
121	                    contextIsolation: true,
122	                    sandbox: true,
123	                    webSecurity: true,
124	                },
125	            });
126	
127	            const wc = this.view.webContents;
128	
129	            wc.on('did-start-loading', () => {
130	                this.pageRevision += 1;
131	                this.updateState({ isLoading: true, error: null });
132	            });
133	
134	            wc.on('did-stop-loading', () => {
135	                this.updateState({
136	                    isLoading: false,
137	                    canGoBack: wc.canGoBack(),
138	                    canGoForward: wc.canGoForward(),
139	                });
140	            });
141	
142	            wc.on('did-navigate', (_e, url) => {
143	                this.updateState({
144	                    url,
145	                    canGoBack: wc.canGoBack(),
146	                    canGoForward: wc.canGoForward(),
147	                    error: null,
148	                });
149	            });
150	
151	            wc.on('did-navigate-in-page', (_e, url) => {
152	                this.pageRevision += 1;
153	                this.updateState({
154	                    url,
155	                    canGoBack: wc.canGoBack(),
156	                    canGoForward: wc.canGoForward(),
157	                });
158	            });
159	
160	            wc.on('page-title-updated', (_e, title) => {
161	                this.updateState({ title });
162	            });
163	
164	            wc.on('did-fail-load', (_e, errorCode, errorDescription, validatedURL, isMainFrame) => {
165	                // Subframe failures and superseded navigations do not invalidate the page.
166	                if (errorCode === -3 || !isMainFrame) return;
167	                this.updateState({
168	                    isLoading: false,
169	                    error: `${errorDescription} (${errorCode}) for ${validatedURL}`,
170	                });
171	            });
172	
173	            // Prevent opening unexpected popups; load in same view or open in external OS browser
174	            wc.setWindowOpenHandler(({ url }) => {
175	                // Always deny a new window, then validate before navigating the
176	                // existing view. HTTP scheme alone does not exclude private hosts.
177	                const revision = this.pageRevision;
178	                void validateSafeUrlAsync(url)
179	                    .then(() => {
180	                        if (this.view?.webContents === wc && this.pageRevision === revision) return wc.loadURL(url);
181	                    })
182	                    .catch(() => log.warn('[BoardroomBrowser] Blocked unsafe popup navigation.'));
183	                return { action: 'deny' };
184	            });
185	
186	            // Restrict will-navigate to safe HTTP/HTTPS only
187	            wc.on('will-navigate', (e, targetNavUrl) => {
188	                try {
189	                    const parsed = new URL(targetNavUrl);
190	                    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
191	                        e.preventDefault();
192	                    }
193	                } catch {
194	                    e.preventDefault();
195	                }
196	            });
197	
198	            // Add view to window content view
199	            parentWin.contentView.addChildView(this.view);
200	            // Default 0x0 hidden until setBounds is called
201	            this.view.setBounds({ x: 0, y: 0, width: 0, height: 0 });
202	            this.view.setVisible(false);
203	        }
204	
205	        // Navigate to target if different or not loaded
206	        if (this.view.webContents.getURL() !== targetUrl) {
207	            await this.view.webContents.loadURL(targetUrl);
208	        }
209	
210	        return { success: true, state: { ...this.currentState } };
211	    }
212	
213	    public setBounds(event: IpcMainInvokeEvent, rawInput: unknown): { success: boolean } {
214	        const input = BoundsSchema.parse(rawInput);
215	        if (!this.view || !this.ownerWindow) {
216	            return { success: false };
217	        }
218	
219	        this.view.setBounds({
220	            x: input.x,
221	            y: input.y,
222	            width: input.width,
223	            height: input.height,
224	        });
225	        this.view.setVisible(input.visible && input.width > 0 && input.height > 0);
226	        return { success: true };
227	    }
228	
229	    public async navigate(event: IpcMainInvokeEvent, rawInput: unknown): Promise<{ success: boolean; url: string }> {
230	        const input = NavigateSchema.parse(rawInput);
231	        const targetUrl = this.normalizeUrl(input.url);
232	
233	        await validateSafeUrlAsync(targetUrl);
234	
235	        if (!this.view) {
236	            await this.attach(event, { initialUrl: targetUrl });
237	            return { success: true, url: targetUrl };
238	        }
239	
240	        await this.view.webContents.loadURL(targetUrl);
241	        return { success: true, url: targetUrl };
242	    }
243	
244	    public goBack(_event: IpcMainInvokeEvent): { success: boolean } {
245	        if (this.view && this.view.webContents.canGoBack()) {
246	            this.view.webContents.goBack();
247	            return { success: true };
248	        }
249	        return { success: false };
250	    }
251	
252	    public goForward(_event: IpcMainInvokeEvent): { success: boolean } {
253	        if (this.view && this.view.webContents.canGoForward()) {
254	            this.view.webContents.goForward();
255	            return { success: true };
256	        }
257	        return { success: false };
258	    }
259	
260	    public reload(_event: IpcMainInvokeEvent): { success: boolean } {
261	        if (this.view) {
262	            this.view.webContents.reload();
263	            return { success: true };
264	        }
265	        return { success: false };
266	    }
267	
268	    public async captureContext(_event: IpcMainInvokeEvent): Promise<{ success: boolean; data: { url: string; title: string; text: string } }> {
269	        if (!this.view) {
270	            throw new Error('Boardroom browser view is not active.');
271	        }
272	
273	        if (this.currentState.isLoading || this.currentState.error) {
274	            throw new Error('Page is loading or failed to load; its content cannot be captured.');
275	        }
276	
277	        const revision = this.pageRevision;
278	        const view = this.view;
279	        const data = await view.webContents.executeJavaScript(`(() => {
280	            return {
281	                title: document.title || '',
282	                url: window.location.href || '',
283	                text: (document.body ? document.body.innerText : '').slice(0, 40000)
284	            };
285	        })()`) as { url: string; title: string; text: string };
286	
287	        if (this.view !== view || this.pageRevision !== revision || this.currentState.isLoading || this.currentState.error) {
288	            throw new Error('Page changed while its content was being captured.');
289	        }
290	        return { success: true, data };
291	    }
292	
293	    public detach(_event: IpcMainInvokeEvent): { success: boolean } {
294	        if (this.view && this.ownerWindow && !this.ownerWindow.isDestroyed()) {
295	            try {
296	                this.view.setVisible(false);
297	                this.ownerWindow.contentView.removeChildView(this.view);
298	            } catch (err) {
299	                log.warn('[BoardroomBrowser] Error removing child view:', err);
300	            }
301	        }
302	        this.pageRevision += 1;
303	        this.view = null;
304	        this.ownerWindow = null;
305	        return { success: true };
306	    }
307	
308	    public openExternal(_event: IpcMainInvokeEvent, rawUrl?: string): { success: boolean } {
309	        const target = rawUrl?.trim() || this.currentState.url;
310	        if (!target) {
311	            return { success: false };
312	        }
313	        try {
314	            const parsed = new URL(target);
315	            if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {
316	                log.warn(`[BoardroomBrowser] Blocked openExternal for non-HTTP(S) protocol: ${parsed.protocol}`);
317	                return { success: false };
318	            }
319	            void shell.openExternal(parsed.toString());
320	            return { success: true };
321	        } catch {
322	            log.warn('[BoardroomBrowser] Blocked openExternal for invalid URL');
323	            return { success: false };
324	        }
325	    }
326	}
