 53	      socket.onopen = () => {
 54	        if (!this.lifecycle.connected(generation)) { socket.close(); return; }
 55	        socket.send(JSON.stringify({ kind: 'client', sessionId: this.sessionId, ticket }));
 56	      };
 57	      socket.onmessage = event => {
 58	        if (!this.lifecycle.isCurrent(generation)) return;
 59	        if (event.data instanceof Blob) { this.onFrame(event.data); return; }
 60	        const value = JSON.parse(event.data);
 61	        if (value.type === 'status') {
 62	          this.fence.control = value.control;
 63	          if (this.fence.controlGeneration !== value.controlGeneration) this.sequence = 0;
 64	          this.fence.controlGeneration = value.controlGeneration;
 65	          if (['ended', 'failed', 'termination_pending'].includes(value.state)) this.close();
 66	        }
 67	        if (value.type === 'navigation') {
 68	          this.fence.navigationGeneration = value.navigationGeneration;
